import json, random, sys, itertools
sys.path.insert(0,'/app')
from checker import Function, check, scalar, shape, join
from interpreter import run
from language import validate, InvalidProgram, StaticError, kind

INT,TEXT,BOOL,UNIT='int','text','bool','unit'
ALLK=[INT,TEXT,BOOL,UNIT]

class Gen:
    def __init__(self, seed, ncells=3, ninputs=2):
        self.r=random.Random(seed)
        self.cellnames=[f"c{i}" for i in range(ncells)]
        self.bounds={}
        self.cells={}
        for n in self.cellnames:
            ntypes=self.r.randint(1,2)
            ts=self.r.sample(ALLK,ntypes)
            self.bounds[n]=frozenset(ts)
            self.cells[n]={'types':ts,'value':self.litval(self.r.choice(ts))}
        self.inputs={}
        for i in range(ninputs):
            n=f"i{i}"
            self.inputs[n]=self.litval(self.r.choice(ALLK))
        self.counter=0
        self.nodes=0

    def litval(self,k):
        r=self.r
        if k==INT:return r.choice([0,1,2,-1,7,42])
        if k==TEXT:return r.choice(["","a","xy","zz"])
        if k==BOOL:return r.choice([True,False])
        return None

    def fresh(self):
        self.counter+=1
        return f"v{self.counter}"

    # type reps: frozenset for scalars, Function for fns
    def rand_scalar_type(self):
        return frozenset(self.r.sample(ALLK,self.r.randint(1,2)))

    def gen_expr(self,env,facts,want,depth):
        # want: frozenset (scalar kinds) or 'fn' or 'any'
        r=self.r
        if isinstance(want,frozenset) and len(want)==1:
            k=next(iter(want))
            return self.gen_scalar(env,facts,k,depth)
        choices=[]
        if isinstance(want,frozenset):
            choices=['lit','var','get','call']
        elif want=='fn':
            choices=['fn','var','call']
        else:
            choices=['lit','var','get','fn','call','add','cat','lt','not','is']
        r.shuffle(choices)
        for c in choices:
            try:
                if c=='lit' and isinstance(want,frozenset):
                    return ['lit',self.litval(r.choice(list(want)))]
                if c=='var':
                    cands=[n for n,t in env.items() if self.match(want,t)]
                    if cands:return ['var',r.choice(cands)]
                if c=='get':
                    cands=[n for n,t in facts.items() if self.match(want,t)]
                    if cands:return ['get',r.choice(cands)]
                if c=='fn' and depth<4:
                    return self.gen_fn(env,depth)
                if c=='call':
                    cal=self.gen_expr(env,facts,'fn',depth+1)
                    return ['call',cal]
                if c in('add','lt') and depth<4:
                    return [c,self.gen_expr(env,facts,scalar(INT),depth+1),self.gen_expr(env,facts,scalar(INT),depth+1)]
                if c=='cat' and depth<4:
                    return ['cat',self.gen_expr(env,facts,scalar(TEXT),depth+1),self.gen_expr(env,facts,scalar(TEXT),depth+1)]
                if c=='not' and depth<4:
                    return ['not',self.gen_expr(env,facts,scalar(BOOL),depth+1)]
                if c=='is' and depth<4:
                    n=r.choice(self.cellnames);return ['is',n,r.choice(ALLK)]
            except GenFail:
                continue
        raise GenFail()

    def match(self,want,t):
        if want=='any':return True
        if want=='fn':return isinstance(t,Function)
        if isinstance(want,frozenset):
            return isinstance(t,frozenset) and t==want
        return False

    def gen_scalar(self,env,facts,k,depth):
        r=self.r
        ops=['lit','var','get']
        if depth<4: ops+=['call','op','is']
        r.shuffle(ops)
        for c in ops:
            try:
                if c=='lit':return ['lit',self.litval(k)]
                if c=='var':
                    cands=[n for n,t in env.items() if isinstance(t,frozenset) and t==scalar(k)]
                    if cands:return ['var',r.choice(cands)]
                if c=='get':
                    cands=[n for n,t in facts.items() if t==scalar(k)]
                    if cands:return ['get',r.choice(cands)]
                if c=='is' and k==BOOL:
                    return ['is',r.choice(self.cellnames),r.choice(ALLK)]
                if c=='call':
                    # find a fn expr returning scalar k; simplest: build fn
                    fn=self.gen_fn(env,depth+1,want_result=scalar(k))
                    return ['call',fn]
                if c=='op':
                    if k==INT:return ['add',self.gen_scalar(env,facts,INT,depth+1),self.gen_scalar(env,facts,INT,depth+1)]
                    if k==TEXT:return ['cat',self.gen_scalar(env,facts,TEXT,depth+1),self.gen_scalar(env,facts,TEXT,depth+1)]
                    if k==BOOL:return r.choice([['lt',self.gen_scalar(env,facts,INT,depth+1),self.gen_scalar(env,facts,INT,depth+1)],
                                                ['not',self.gen_scalar(env,facts,BOOL,depth+1)]])
            except GenFail:
                continue
        raise GenFail()

    def gen_fn(self,env,depth,want_result=None):
        # build a fn: random body, result expr. capture env copy, facts=bounds
        inner=dict(env)
        fresh=dict(self.bounds)
        body=self.gen_block(inner,fresh,depth+1,maxlen=self.r.randint(0,3))
        if want_result is None:
            if self.r.random()<0.4:
                rt='fn'
            else:
                rt=self.rand_scalar_type()
            res=self.gen_expr(inner,fresh,rt,depth+1)
        else:
            res=self.gen_expr(inner,fresh,want_result,depth+1)
        return ['fn',body,res]

    def gen_block(self,env,facts,depth,maxlen=4):
        r=self.r
        body=[]
        n=r.randint(1,maxlen)
        for _ in range(n):
            st=self.gen_stmt(env,facts,depth)
            if st is not None:
                body.append(st)
        return body

    def gen_stmt(self,env,facts,depth):
        r=self.r
        ops=['let','set','eval','if','repeat','assign']
        if depth>3: ops=['let','set','eval']
        op=r.choice(ops)
        try:
            if op=='let':
                n=self.fresh()
                if r.random()<0.5:
                    e=self.gen_fn(env,depth+1)
                else:
                    e=self.gen_expr(env,facts,self.rand_scalar_type(),depth+1)
                # compute type to update env: run checker expr
                t,w=check_expr_type(e,env,facts,self.bounds)
                env[n]=t
                return ['let',n,e]
            if op=='assign':
                cands=[n for n in env if n not in self.inputs]
                if not cands:return self.gen_stmt(env,facts,depth)
                n=r.choice(cands);t=env[n]
                if isinstance(t,Function):
                    e=self.gen_fn(env,depth+1,want_result=t.result)
                else:
                    e=self.gen_expr(env,facts,t,depth+1)
                env[n]=t
                return ['assign',n,e]
            if op=='set':
                n=r.choice(self.cellnames)
                want=self.bounds[n]
                e=self.gen_expr(env,facts,want,depth+1)
                tt,w=check_expr_type(e,env,facts,self.bounds)
                facts[n]=tt
                return ['set',n,e]
            if op=='eval':
                e=self.gen_expr(env,facts,'any',depth+1)
                return ['eval',e]
            if op=='if':
                use_is=r.random()<0.6
                if use_is:
                    n=r.choice(self.cellnames);k=r.choice(ALLK)
                    guard=['is',n,k]
                    fa=dict(facts);fb=dict(facts)
                    fa[n]=facts[n]&scalar(k);fb[n]=facts[n]-scalar(k)
                    ea=dict(env);eb=dict(env)
                    ta= self.gen_block(ea,fa,depth+1,maxlen=3) if all(fa.values()) else []
                    tb= self.gen_block(eb,fb,depth+1,maxlen=3) if all(fb.values()) else []
                    # merge like checker
                    if not all(fb.values()):
                        for nn in env:env[nn]=ea[nn]
                        for nn in facts:facts[nn]=fa[nn]
                    elif not all(fa.values()):
                        for nn in env:env[nn]=eb[nn]
                        for nn in facts:facts[nn]=fb[nn]
                    else:
                        for nn in env:env[nn]=join(ea[nn],eb[nn])
                        for nn in facts:facts[nn]=fa[nn]|fb[nn]
                    return ['if',guard,ta,tb]
                else:
                    guard=self.gen_scalar(env,facts,BOOL,depth+1)
                    ea=dict(env);eb=dict(env);fa=dict(facts);fb=dict(facts)
                    ta=self.gen_block(ea,fa,depth+1,maxlen=3)
                    tb=self.gen_block(eb,fb,depth+1,maxlen=3)
                    for nn in env:env[nn]=join(ea[nn],eb[nn])
                    for nn in facts:facts[nn]=fa[nn]|fb[nn]
                    return ['if',guard,ta,tb]
            if op=='repeat':
                cnt=self.gen_scalar(env,facts,INT,depth+1)
                # iterate join like checker (approximate: run body 3 times joining)
                for _ in range(4):
                    ne=dict(env);nf=dict(facts)
                    body=self.gen_block(ne,nf,depth+1,maxlen=3)
                    for nn in env:
                        env[nn]=join(env[nn],ne[nn])
                    for nn in facts:facts[nn]|=nf[nn]
                return ['repeat',cnt,body]
        except GenFail:
            return None
        return None

class GenFail(Exception):pass

def check_expr_type(e,env,facts,bounds):
    # minimal mirror of checker.expr to keep generator's env/facts consistent
    from checker import Checker
    c=Checker.__new__(Checker)
    c.bounds=bounds;c.inputs=set()
    c.coverage=set()
    env2=dict(env);facts2=dict(facts)
    t,w=c.expr(e,env2,facts2)
    facts.update(facts2)
    return t,w

def gen_program(seed):
    g=Gen(seed,ncells=random.Random(seed).randint(1,4),ninputs=random.Random(seed+1).randint(0,2))
    env={n:scalar(kind(v)) for n,v in g.inputs.items()}
    facts={n:scalar(kind(d['value'])) for n,d in g.cells.items()}
    body=g.gen_block(env,facts,1,maxlen=6)
    return {'cells':g.cells,'inputs':g.inputs,'body':body}

def main():
    import sys
    start=int(sys.argv[1]);count=int(sys.argv[2])
    tested=accepted=errors=0
    for seed in range(start,start+count):
        try:
            p=gen_program(seed)
        except Exception:
            continue
        try:
            validate(p)
        except Exception:
            continue
        tested+=1
        try:
            check(p)
        except StaticError:
            continue
        except Exception:
            continue
        accepted+=1
        try:
            res=run(p)
        except Exception as e:
            continue
        if res['status']=='type_error':
            errors+=1
            print(f"FOUND seed={seed} steps={res['steps']} msg={res['message']}")
            with open(f'/tmp/fuzz/found_{seed}.json','w') as f:
                json.dump(p,f)
            if errors>=5:
                break
    print(f"tested={tested} accepted={accepted} errors={errors}")

main()
