from checker import Function, check, scalar, shape, join
from interpreter import run
from language import validate, InvalidProgram, StaticError, kind

INT,TEXT,BOOL,UNIT='int','text','bool','unit'
ALLK=[INT,TEXT,BOOL,UNIT]
class GenFail(Exception):pass

def scal_lit(r,k):
    if k==INT:return r.choice([0,1,2,-1,7,42])
    if k==TEXT:return r.choice(["","a","xy","zz"])
    if k==BOOL:return r.choice([True,False])
    return None

class G:
    def __init__(self,seed):
        r=self.r=random.Random(seed)
        self.cells={};self.bounds={}
        for i in range(r.randint(1,4)):
            n=f"c{i}";ts=r.sample(ALLK,r.choice([1,2,2]))
            self.bounds[n]=frozenset(ts)
            self.cells[n]={'types':ts,'value':scal_lit(r,r.choice(ts))}
        self.inputs={}
        for i in range(r.randint(0,3)):
            self.inputs[f"i{i}"]=scal_lit(r,r.choice(ALLK))
