            opts=['lit','var','get','op','call','is'] if len(want)==1 else ['lit','var','get','call']
        elif want=='fn':
            opts=['fnvar','fnnew','call']
        else:
            opts=['lit','var','get','op','call','is','fnnew']
        r.shuffle(opts)
        for o in opts:
            try:
                if o=='lit' and isinstance(want,frozenset):
                    return ['lit',scal_lit(r,r.choice(sorted(want)))]
                if o=='var':
                    c=[n for n,t in env.items() if isinstance(t,frozenset) and (not isinstance(want,frozenset) or t==want)]
                    if c:return ['var',r.choice(c)]
                if o=='get':
                    c=[n for n,t in facts.items() if (not isinstance(want,frozenset) or t==want)]
                    if c:return ['get',r.choice(c)]
                if o=='is' and (not isinstance(want,frozenset) or want==scalar(BOOL)):
                    return ['is',r.choice(list(self.bounds)),r.choice(ALLK)]
                if o=='op' and isinstance(want,frozenset) and len(want)==1:
                    k=next(iter(want))
                    if k==INT:return ['add',self.expr(env,facts,scalar(INT),depth+1),self.expr(env,facts,scalar(INT),depth+1)]
                    if k==TEXT:return ['cat',self.expr(env,facts,scalar(TEXT),depth+1),self.expr(env,facts,scalar(TEXT),depth+1)]
                    if k==BOOL:return r.choice([['lt',self.expr(env,facts,scalar(INT),depth+1),self.expr(env,facts,scalar(INT),depth+1)],['not',self.expr(env,facts,scalar(BOOL),depth+1)]])
                if o=='fnnew' and depth<3:
                    return self.fn(env,depth+1)
                if o=='fnvar':
                    c=[n for n,t in env.items() if isinstance(t,Function)]
                    if c:return ['var',r.choice(c)]
                if o=='call' and depth<3:
                    return ['call',self.expr(env,facts,'fn',depth+1)]
            except GenFail:
                continue
        raise GenFail()
    def fn(self,env,depth,want_result=None):
        inner=dict(env);fresh=dict(self.bounds)
        body=self.block(inner,fresh,depth,self.r.randint(0,3))
        if want_result is None:
            wr=self.r.choice([self.randt(),'fn'])
            res=self.expr(inner,fresh,wr,depth+1)
        else:
            res=self.expr(inner,fresh,want_result,depth+1)
        return ['fn',body,res]
    def randt(self):
        return frozenset(self.r.sample(ALLK,self.r.randint(1,2)))
    def block(self,env,facts,depth,n):
