                        for nn in facts:facts[nn]=fa[nn]
                    elif not all(fa.values()):
                        for nn in env:env[nn]=eb[nn]
                        for nn in facts:facts[nn]=fb[nn]
                    else:
                        for nn in env:env[nn]=join(ea[nn],eb[nn])
                        for nn in facts:facts[nn]=fa[nn]|fb[nn]
                    return ['if',g,ta,tb]
                else:
                    g=self.expr(env,facts,scalar(BOOL),depth+1)
                    ea=dict(env);eb=dict(env);fa=dict(facts);fb=dict(facts)
                    ta=self.block(ea,fa,depth+1,r.randint(0,3));tb=self.block(eb,fb,depth+1,r.randint(0,3))
                    for nn in env:env[nn]=join(ea[nn],eb[nn])
                    for nn in facts:facts[nn]=fa[nn]|fb[nn]
                    return ['if',g,ta,tb]
            if op=='repeat':
                cnt=self.expr(env,facts,scalar(INT),depth+1)
                body=None
                for _ in range(4):
                    ne=dict(env);nf=dict(facts)
                    body=self.block(ne,nf,depth+1,r.randint(1,3))
                    for nn in env:env[nn]=join(env[nn],ne[nn])
                    for nn in facts:facts[nn]|=nf[nn]
                return ['repeat',cnt,body]
        except GenFail:
            return None
        return None

from checker import Checker
def expr_type(e,env,facts,bounds):
    c=Checker.__new__(Checker);c.bounds=bounds;c.inputs=set();c.coverage=set()
    f2=dict(facts);t,w=c.expr(e,dict(env),f2);facts.update(f2);return t
def fn_type(e,env,bounds):
    c=Checker.__new__(Checker);c.bounds=bounds;c.inputs=set();c.coverage=set()
    t,w=c.expr(e,dict(env),dict(bounds));return t

def gen(seed):
    g=G(seed)
    env={n:scalar(kind(v)) for n,v in g.inputs.items()}
    facts={n:scalar(kind(d['value'])) for n,d in g.cells.items()}
    body=g.block(env,facts,1,g.r.randint(2,7))
    return {'cells':g.cells,'inputs':g.inputs,'body':body}

VALUES={INT:[0,1,-3,99],TEXT:["","a","q"],BOOL:[True,False],UNIT:[None]}

def main():
    start=int(sys.argv[1]);count=int(sys.argv[2])
    tested=acc=err=0
    for seed in range(start,start+count):
        try:p=gen(seed)
        except Exception:continue
        try:validate(p)
        except Exception:continue
        tested+=1
        try:check(p)
        except Exception:continue
        acc+=1
        # input variation
        inames=list(p['inputs'])
        pools=[VALUES[kind(p['inputs'][n])] for n in inames]
        for combo in itertools.product(*pools) if inames else [()]:
            p2=json.loads(json.dumps(p))
            for n,v in zip(inames,combo):p2['inputs'][n]=v
            try:res=run(p2)
