            if res['status']=='type_error':
                err+=1
                print(f"FOUND seed={seed} combo={combo} steps={res['steps']} msg={res['message']}")
                with open(f'/tmp/fuzz/found_{seed}.json','w') as f:json.dump(p2,f)
                if err>=3:
                    print(f"tested={tested} acc={acc} err={err}");return
    print(f"tested={tested} acc={acc} err={err}")
main()
