import json, random, sys, itertools
sys.path.insert(0,'/app')
from checker import Function, check, scalar, shape, join
from interpreter import run
from language import validate, InvalidProgram, StaticError, kind

INT,TEXT,BOOL,UNIT='int','text','bool','unit'
ALLK=[INT,TEXT,BOOL,UNIT]
class GenFail(Exception):pass
def scal_lit(r,k):
    if k==INT:return r.choice([0,1,2,-1,7,42])
    if k==TEXT:return r.choice(["","a","xy","zz"])
    if k==BOOL:return r.choice([True,False])
    return None

# Build random program pieces with checker to keep env/facts; but also try divergent shapes.
from checker import Checker
def mkchecker(bounds,inputs):
    c=Checker.__new__(Checker);c.bounds=bounds;c.inputs=set(inputs);c.coverage=set();return c

class G:
    def __init__(self,seed):
        r=self.r=random.Random(seed)
        self.cells={};self.bounds={}
        for i in range(r.randint(1,4)):
            n=f"c{i}";ts=r.sample(ALLK,r.choice([1,2,2,3]))
            self.bounds[n]=frozenset(ts)
            self.cells[n]={'types':ts,'value':scal_lit(r,r.choice(ts))}
        self.inputs={}
        for i in range(r.randint(0,3)):
            self.inputs[f"i{i}"]=scal_lit(r,r.choice(ALLK))
        self.ctr=0
        self.fnvars=[]  # names of fn-typed vars in scope (top level tracking)
    def fresh(self):
        self.ctr+=1;return f"v{self.ctr}"

    # generate a random expression and return (json, type) using checker to type it
    def expr(self,env,facts,want,depth):
        r=self.r
        for _ in range(30):
            e=self._expr(env,facts,want,depth)
            if e is None:continue
            try:
                f2=dict(facts);t=type_of(e,env,f2,self.bounds)
            except StaticError:continue
            except Exception:continue
            if want=='any' or (want=='fn' and isinstance(t,Function)) or (isinstance(want,frozenset) and t==want):
                facts.update(f2);return e
        raise GenFail()
    def _expr(self,env,facts,want,depth):
        r=self.r
        if depth>4:
            # only leaves
            c=self.leaf(env,facts,want)
            if c is None:raise GenFail()
            return c
        opts=['leaf','leaf','add','cat','lt','not','is','call','fn']
        o=r.choice(opts)
        if o=='leaf':
            c=self.leaf(env,facts,want)
            if c is None:raise GenFail()
            return c
        if o=='add':return ['add',self.expr(env,facts,scalar(INT),depth+1),self.expr(env,facts,scalar(INT),depth+1)]
        if o=='cat':return ['cat',self.expr(env,facts,scalar(TEXT),depth+1),self.expr(env,facts,scalar(TEXT),depth+1)]
        if o=='lt':return ['lt',self.expr(env,facts,scalar(INT),depth+1),self.expr(env,facts,scalar(INT),depth+1)]
        if o=='not':return ['not',self.expr(env,facts,scalar(BOOL),depth+1)]
        if o=='is':return ['is',r.choice(list(self.bounds)),r.choice(ALLK)]
        if o=='call':return ['call',self.expr(env,facts,'fn',depth+1)]
        if o=='fn':return self.fn(env,depth+1)
        raise GenFail()
    def leaf(self,env,facts,want):
        r=self.r
        c=[]
        if isinstance(want,frozenset):c.append('lit')
        c+= ['var','get']
        if want=='fn':c=['fnvar']
        r.shuffle(c)
        for o in c:
            if o=='lit':return ['lit',scal_lit(r,r.choice(sorted(want)))]
