import json, random, sys, itertools
sys.path.insert(0,'/app')
import checker as CK
import interpreter as IP
from checker import Function, scalar, shape, join
from language import validate, StaticError, kind

INT,TEXT,BOOL,UNIT='int','text','bool','unit'
ALLK=[INT,TEXT,BOOL,UNIT]

# ---- instrumented checker: record static type per expr node id ----
class RecChecker(CK.Checker):
    def __init__(self,p):
        super().__init__(p)
        self.node_types={}  # id -> list of types
    def expr(self,e,env,facts):
        t,w=super().expr(e,env,facts)
        if isinstance(t,Function):
            key=('fn',)+shape(t)
        else:
            key=('sc',tuple(sorted(t)))
        self.node_types.setdefault(id(e),set()).add(key)
        return t,w

def static_types(p):
    c=RecChecker(p)
    env={n:scalar(kind(v)) for n,v in p['inputs'].items()}
    facts={n:scalar(kind(d['value'])) for n,d in p['cells'].items()}
    c.block(p['body'],env,facts)
    return c.node_types

# ---- instrumented interpreter: record runtime kind per expr node id ----
class RecMachine(IP.Machine):
    def __init__(self,p,limit=IP.MAX_STEPS):
        super().__init__(p,limit)
        self.node_kinds={}  # id -> set of kinds
    def tick(self,label):
        super().tick(label)
        # after expression tick we don't know value yet; hook below instead

# easier: wrap values.append by checking the current work item — complex. 
# Instead: re-implement execute to record after each expression evaluation.
def run_rec(p,limit=IP.MAX_STEPS):
    IP.validate(p)
    m=RecMachine(p,limit)
    node_kinds={}
    orig_append=m.values.append
    # We can't easily tie value pushes to nodes without deeper hooks.
    return m

# Simpler approach: monkeypatch Machine.execute is too complex.
# Alternative: walk AST, and for each 'get'/'var'/'call'/'add' etc node, the interpreter
# pushes exactly one value; we override execute minimally by subclassing and intercepting
# the 'expression' pop handling.

class TraceMachine(IP.Machine):
    def __init__(self,p,limit=IP.MAX_STEPS):
        super().__init__(p,limit)
        self.kinds={}
    def execute(self,body,env):
        self.schedule(body,env)
        while self.work:
            tag,x,env=self.work.pop()
            if tag=='expression':
                before=len(self.values)
                self.handle_expression(x,env)
                # after handling, expression may have pushed continuations instead of value
                # only leaf expressions push a value immediately
                if len(self.values)==before+1:
                    v=self.values[-1]
                    k='function' if isinstance(v,IP.Closure) else kind(v)
                    self.kinds.setdefault(id(x),set()).add(k)
            else:
                self.handle_other(tag,x,env)
    def handle_expression(self,x,env):
        op=x[0];self.tick('expr:'+op)
        if op=='lit':self.values.append(x[1])
        elif op=='var':self.values.append(env[x[1]])
        elif op=='get':self.values.append(self.cells[x[1]])
        elif op=='is':self.values.append(kind(self.cells[x[1]])==x[2])
        elif op=='fn':self.values.append(IP.Closure(x[1],x[2],env.copy()))
        elif op in ('call','not'):
            self.work.append((op,None,env));self.work.append(('expression',x[1],env))
        else:
            self.work.append(('binary',op,env));self.work.append(('expression',x[2],env));self.work.append(('expression',x[1],env))
    def handle_other(self,tag,x,env):
        if tag=='statement':
            op=x[0];self.tick('stmt:'+op)
            if op in ('let','assign','set'):
                self.work.append((op,x[1],env));self.work.append(('expression',x[2],env))
            elif op=='eval':
                self.work.append(('discard',None,env));self.work.append(('expression',x[1],env))
            else:
                self.work.append((op,x,env));self.work.append(('expression',x[1],env))
        elif tag in ('let','assign'):env[x]=self.values.pop()
        elif tag=='set':self.cells[x]=self.values.pop()
        elif tag=='discard':self.values.pop()
        elif tag=='call':
            f=self.values.pop();self.require(f,'function');local=f.captured.copy()
            self.work.append(('expression',f.result,local));self.schedule(f.body,local)
        elif tag=='not':
            a=self.values.pop();self.require(a,'bool');self.values.append(not a)
        elif tag=='binary':
            b=self.values.pop();a=self.values.pop();k='text' if x=='cat' else 'int'
            self.require(a,k);self.require(b,k)
            value=(a<b) if x=='lt' else (a+b)[:1024] if x=='cat' else ((a+b+2**31)%2**32)-2**31
            self.values.append(value)
        elif tag=='if':
            cond=self.values.pop();self.require(cond,'bool')
            self.work.append(('scope',set(env),env));self.schedule(x[2] if cond else x[3],env)
        elif tag=='repeat':
            count=self.values.pop();self.require(count,'int')
            old=set(env)
            for _ in range(max(0,min(3,count))):
                self.work.append(('scope',old,env));self.schedule(x[2],env)
        elif tag=='scope':
            for n in set(env)-x:del env[n]
        else:raise AssertionError(tag)

def check_divergence(p):
    """Return a list of (node_id, static_types, runtime_kinds) where runtime not subset of static."""
    try:
        st=static_types(p)
    except StaticError:
        return None  # rejected
    m=TraceMachine(p)
    try:
        m.execute(p['body'],p['inputs'].copy())
        status='normal'
    except IP.RuntimeTypeError:
        status='type_error'
    except IP.StepLimit:
        status='step_limit'
    rk=m.kinds
    bad=[]
    for nid,kinds in rk.items():
        static=st.get(nid)
        if static is None:continue
        # compute union of static scalar kinds
        sc=set()
        isfn=False
        for t in static:
            if t[0]=='sc':sc.update(t[1])
            else:isfn=True
        for k in kinds:
            if k=='function':
                if not isfn:bad.append((nid,static,kinds,'fn-vs-scalar'))
            else:
                if k not in sc:bad.append((nid,static,kinds,f'{k} not in {sc}'))
    return status,bad

