import sys
sys.path.insert(0,'/app')
from language import kind, RuntimeTypeError, StepLimit

# Independent big-step evaluator, written directly from LANGUAGE.md prose.
class Closure:
    __slots__=('body','result','captured')
    def __init__(self,body,result,captured):
        self.body=body;self.result=result;self.captured=captured

def req(v,k):
    actual='function' if isinstance(v,Closure) else kind(v)
    if actual!=k:raise RuntimeTypeError('expected '+k+', got '+actual)

class E:
    def __init__(self,p):
        self.cells={n:d['value'] for n,d in p['cells'].items()}
    def ev(self,e,env):
        op=e[0]
        if op=='lit':return e[1]
        if op=='var':return env[e[1]]
        if op=='get':return self.cells[e[1]]
        if op=='is':return kind(self.cells[e[1]])==e[2]
        if op=='fn':return Closure(e[1],e[2],dict(env))
        if op=='call':
            f=self.ev(e[1],env);req(f,'function')
            local=dict(f.captured)
            self.exec_block(f.body,local)
            return self.ev(f.result,local)
        if op=='not':
            a=self.ev(e[1],env);req(a,'bool');return not a
        a=self.ev(e[1],env);b=self.ev(e[2],env)
        k='text' if op=='cat' else 'int'
        req(a,k);req(b,k)
        if op=='lt':return a<b
        if op=='cat':return (a+b)[:1024]
        return ((a+b+2**31)%2**32)-2**31
    def exec_block(self,body,env):
        # returns; new lets are scoped by caller via old-set deletion
        for s in body:self.st(s,env)
    def st(self,s,env):
        op=s[0]
        if op=='let':
            v=self.ev(s[2],env);env[s[1]]=v
        elif op=='assign':
            v=self.ev(s[2],env);env[s[1]]=v
        elif op=='set':
            v=self.ev(s[2],env);self.cells[s[1]]=v
        elif op=='eval':
            self.ev(s[1],env)
        elif op=='if':
            c=self.ev(s[1],env);req(c,'bool')
            old=set(env)
            self.exec_block(s[2] if c else s[3],env)
            for n in set(env)-old:del env[n]
        elif op=='repeat':
            c=self.ev(s[1],env);req(c,'int')
            old=set(env)
            for _ in range(max(0,min(3,c))):
                self.exec_block(s[2],env)
                for n in set(env)-old:del env[n]
    def run(self):
        self.exec_block(self.body,self.env0)
def run_spec(p):
    e=E(p)
    try:
        e.body=p['body'];e.env0=dict(p['inputs'])
        e.exec_block(p['body'],e.env0)
    except RuntimeTypeError:return ('type_error',dict(e.cells))
    return ('normal',dict(e.cells))
